  address: Int,
  data: List[Int],
  timeout_ms: Int64
) -> (Int, ())

@external(c, "__emela_peripheral_i2c_master_receive")
fn i2c_master_receive(
  id: I2cId,
  address: Int,
  size: Int,
  timeout_ms: Int64
) -> (Int, List[Int])

@external(c, "__emela_peripheral_i2c_memory_write")
fn i2c_memory_write(
  id: I2cId,
  address: Int,
  memory_address: Int,
  address_size: MemoryAddressSize,
  data: List[Int],
  timeout_ms: Int64
